export type CharacterId =
  | "kang-taejun"
  | "kwon-sehyun"
  | "michael"
  | "seo-yuan"
  | "seo-ijun"
  | "yoon-siwoo"
  | "han-yunseo"
  | "kim-ming"
  | "park-jieun"
  | "saebyeok"
  | "seoyeon"
  | "soha"
  | "jiyoon"
  | "harin"
  | "neo"
  | "yeoni";

export type LoveStats = {
  affection: number;
  trust: number;
  chemistry: number;
  tension: number;
  stability: number;
};

export type LoveCharacter = {
  id: CharacterId;
  name: string;
  gender: "male" | "female";
  asset: string;
  dayMaster: "병화" | "경금" | "계수" | "기토" | "임수" | "갑목" | "정화" | "신금" | "을목";
  element: "fire" | "metal" | "water" | "earth" | "wood";
  yinYang: "yin" | "yang";
  archetype: string;
  keywords: string[];
  matchKeywords?: string[];
  sajuMatchProfile?: {
    primaryDayMasters?: string[];
    elementBias?: string[];
    yinYang?: "yin" | "yang" | "balanced";
    tenGodHints?: string[];
    charmHints?: string[];
    relationshipKeywords?: string[];
  };
  profileLine: string;
  personality: string;
  speechStyle: string;
  likes: {
    places: string[];
    foods: string[];
    topics: string[];
    gifts?: string[];
  };
  dislikes: {
    places: string[];
    foods: string[];
    behaviors: string[];
  };
  affectionTriggers: string[];
  trustTriggers: string[];
  conflictPattern: string;
  bestApproach: string;
  palette: {
    shell: string;
    scene: string;
    halo: string;
    accent: string;
    button: string;
    chip: string;
  };
};

export type LoveChoice = {
  id: string;
  text: string;
  effects: Partial<LoveStats>;
  response: string;
  insight: string;
};

export type LoveScene = {
  id: string;
  characterId: CharacterId;
  chapter: number;
  location: string;
  title: string;
  situation: string;
  dialogue: string;
  choices: LoveChoice[];
};

type LoveSceneDefinition = Omit<LoveScene, "title"> & {
  titleKey: string;
};

export type LoveSceneTitleLocale = "ko" | "en" | "ja" | "zh-CN" | "zh-TW" | "vi" | "hi" | "es" | "fr" | "de" | "nl" | "ms";

export type ChoiceLog = {
  sceneId: string;
  choiceId: string;
  tone: string;
  effects: Partial<LoveStats>;
};

export const INITIAL_STATS: LoveStats = {
  affection: 48,
  trust: 46,
  chemistry: 44,
  tension: 30,
  stability: 48,
};

/**
 * 로케일화 대상인 캐릭터 표면 4필드의 **한국어 정본**. `LOVE_CHARACTERS` 가 이 표를 펼쳐
 * 쓰므로 사본이 아니라 유일한 출처다.
 *
 * 다른 로케일은 `LoveSimulationEngine` 이 걸어 둔 `useLoveSimCopy("characters", LOVE_CHARACTER_COPY_KO)`
 * 가 사전(`loveSimulation.characters.*`, 저작 정본 `i18n/authored/loveSimulation-02.json`)에서
 * 가져간다. 문구를 고치면 사전 ko 도 같이 고쳐야 한다 — 안 고치면 한국어만 바뀌고 나머지
 * 11개 로케일이 옛 문장을 계속 서빙한다(가드가 대조한다).
 *
 * 🔴 여기 없는 캐릭터 한국어(`personality`·`speechStyle`·`likes`·`conflictPattern`·장면 본문)는
 * 아직 로케일화 전이다 — 콘텐츠 번역 슬라이스 3·4 소관이고, 그때까지 비-ko 화면은
 * 캐릭터 이름·소개만 그 언어로 나온다.
 *
 * 🔴 객체 리터럴로 둔다. 가드(`__tests__/fixtures/scoped-copy-i18n-guard.js`)가 AST 로 이 선언을
 * 읽어 검사 대상 키를 정하므로, `LOVE_CHARACTERS` 에서 map 으로 만들어 내면 검사가 통째로 죽는다.
 */
export type LoveCharacterCopyEntry = {
  name: string;
  archetype: string;
  profileLine: string;
  bestApproach: string;
};

